import { c as PROVIDER_ID, d as resolveAuth, f as selectClaudePromptForModel, l as buildPluginModels, m as registerFileToolReminders, p as FILE_TOOL_GUIDANCE } from "./src-C0aLondj.js";
//#region src/server.ts
var SHELL_CWD_NOTE = "Each shell tool call starts in the working directory from <env>; a `cd` lasts only for that call. When possible, avoid changing directories in the command and set the shell tool's `workdir` instead.";
var server_default = {
	id: "anthropic-sdk",
	async setup(ctx) {
		const isOAuth = resolveAuth(ctx.options).isOAuth;
		const providerPackage = `aisdk:${new URL(
			/* @vite-ignore */
			"./index.js",
			import.meta.url
		).href}`;
		await ctx.provider.transform((editor) => {
			const models = Object.entries(buildPluginModels(isOAuth)).map(([id, definition]) => ({
				id,
				modelID: id,
				providerID: PROVIDER_ID,
				name: definition.name,
				package: providerPackage,
				capabilities: {
					tools: definition.tool_call,
					input: definition.modalities.input,
					output: definition.modalities.output
				},
				limit: definition.limit,
				cost: [{
					input: definition.cost.input,
					output: definition.cost.output,
					cache: {
						read: definition.cost.cache_read,
						write: definition.cost.cache_write
					}
				}],
				settings: "options" in definition ? definition.options : {},
				variants: Object.entries("variants" in definition ? definition.variants : {}).map(([variantID, settings]) => ({
					id: variantID,
					settings
				})),
				time: { released: 0 },
				status: "active",
				enabled: true
			}));
			editor.add({
				info: {
					id: PROVIDER_ID,
					name: "Anthropic SDK",
					activation: "enabled",
					package: providerPackage,
					settings: { ...ctx.options }
				},
				models
			});
		});
		await ctx.session.hook("context", (event) => {
			const first = event.system[0];
			const index = first && ["You are powered by the model named", "Here is some useful information about the environment"].map((marker) => first.text.indexOf(marker)).filter((position) => position >= 0).toSorted((a, b) => a - b)[0];
			const tail = index != null ? [{
				...first,
				text: first.text.slice(index)
			}, ...event.system.slice(1)] : event.system.slice(1);
			event.system.splice(0, event.system.length, {
				type: "text",
				text: `${selectClaudePromptForModel(event.model.id)}\n${FILE_TOOL_GUIDANCE}\n${SHELL_CWD_NOTE}\n`
			}, ...tail.map((part) => Object.assign({}, part, { text: part.text.replace("Is directory a git repo: yes", "Is a git repository: true").replace("Is directory a git repo: no", "Is a git repository: false") })));
			event.options.maxTokens ??= 64e3;
		}, { providerID: PROVIDER_ID });
		return registerFileToolReminders(ctx, PROVIDER_ID);
	}
};
//#endregion
export { server_default as default };
